def noise_cov_YY(f, d_12, d_21, d_13, d_31, d_23, d_32, Soms_d, Sa_a):
    """Unequal-arm TDI-2 ``C_YY`` in relative-frequency units.

    Args:
        f: Frequency array (Hz).
        d_12, d_21, d_13, d_31, d_23, d_32: Per-link light travel
            times (s); ``d_ij`` is the delay from S/C ``j`` to ``i``.
        Soms_d: Squared OMS displacement level (m^2), i.e.
            ``LISAModel.Soms_d``.
        Sa_a: Squared acceleration level, i.e. ``LISAModel.Sa_a``.

    Returns:
        ``C_YY`` evaluated on ``f``.
    """
    f_oms = 2e-3
    f_tm1 = 0.4e-3
