    f_oms = 2e-3
    f_tm1 = 0.4e-3
    f_tm2 = 8e-3
    return (1/4)*(16*np.pi**4*Soms_d*f**2*f_tm2**4*(f**4 + f_oms**4)*(-np.exp(2.0*1j*np.pi*d_32*f) + np.exp(2.0*1j*np.pi*f*(d_13 + d_31 + d_32)) + np.exp(1j*np.pi*f*(2.0*d_13 + 2.0*d_23 + 2.0*d_31 + 4.0*d_32)) - np.exp(1j*np.pi*f*(4.0*d_13 + 2.0*d_23 + 4.0*d_31 + 4.0*d_32)))*(np.exp(1j*np.pi*f*(4.0*d_12 + 4.0*d_21 + 2.0*d_23 + 2.0*d_32)) - np.exp(1j*np.pi*f*(6.0*d_12 + 6.0*d_21 + 2.0*d_23 + 2.0*d_32)) - np.exp(1j*np.pi*f*(6.0*d_12 + 6.0*d_21 + 4.0*d_23 + 4.0*d_32)) + np.exp(1j*np.pi*f*(8.0*d_12 + 8.0*d_21 + 4.0*d_23 + 4.0*d_32)))*np.exp(1j*np.pi*f*(40.0*d_12 + 40.0*d_21 + 46.0*d_23 + 22.0*d_32)) + 16*np.pi**4*Soms_d*f**2*f_tm2**4*(f**4 + f_oms**4)*(np.exp(2.0*1j*np.pi*f*(d_13 + d_31)) + np.exp(2.0*1j*np.pi*f*(d_13 + d_23 + d_31 + d_32)) - np.exp(1j*np.pi*f*(4.0*d_13 + 2.0*d_23 + 4.0*d_31 + 2.0*d_32)) - 1)*(np.exp(1j*np.pi*f*(4.0*d_12 + 4.0*d_21 + 8.0*d_23 + 2.0*d_32)) - np.exp(1j*np.pi*f*(6.0*d_12 + 6.0*d_21 + 8.0*d_23 + 2.0*d_32)) - np.exp(1j*np.pi*f*(6.0*d_12 + 6.0*d_21 + 10.0*d_23 + 4.0*d_32)) + np.exp(1j*np.pi*f*(8.0*d_12 + 8.0*d_21 + 10.0*d_23 + 4.0*d_32)))*np.exp(1j*np.pi*f*(40.0*d_12 + 40.0*d_21 + 38.0*d_23 + 22.0*d_32)) + Sa_a*(f**2 + f_tm1**2)*(f**4 + f_tm2**4)*((-np.exp(2.0*1j*np.pi*d_32*f) + np.exp(2.0*1j*np.pi*f*(d_13 + d_31 + d_32)) + np.exp(1j*np.pi*f*(2.0*d_13 + 2.0*d_23 + 2.0*d_31 + 4.0*d_32)) - np.exp(1j*np.pi*f*(4.0*d_13 + 2.0*d_23 + 4.0*d_31 + 4.0*d_32)))*np.exp(2.0*1j*np.pi*d_23*f) + np.exp(2.0*1j*np.pi*f*(d_13 + d_31)) + np.exp(2.0*1j*np.pi*f*(d_13 + d_23 + d_31 + d_32)) - np.exp(1j*np.pi*f*(4.0*d_13 + 2.0*d_23 + 4.0*d_31 + 2.0*d_32)) - 1)*((np.exp(1j*np.pi*f*(4.0*d_12 + 4.0*d_21 + 2.0*d_23 + 2.0*d_32)) - np.exp(1j*np.pi*f*(6.0*d_12 + 6.0*d_21 + 2.0*d_23 + 2.0*d_32)) - np.exp(1j*np.pi*f*(6.0*d_12 + 6.0*d_21 + 4.0*d_23 + 4.0*d_32)) + np.exp(1j*np.pi*f*(8.0*d_12 + 8.0*d_21 + 4.0*d_23 + 4.0*d_32)))*np.exp(1j*np.pi*f*(8.0*d_12 + 8.0*d_21 + 12.0*d_23 + 4.0*d_32)) + np.exp(1j*np.pi*f*(12.0*d_12 + 12.0*d_21 + 14.0*d_23 + 6.0*d_32)) - np.exp(1j*np.pi*f*(14.0*d_12 + 14.0*d_21 + 14.0*d_23 + 6.0*d_32)) - np.exp(1j*np.pi*f*(14.0*d_12 + 14.0*d_21 + 16.0*d_23 + 8.0*d_32)) + np.exp(1j*np.pi*f*(16.0*d_12 + 16.0*d_21 + 16.0*d_23 + 8.0*d_32)))*np.exp(1j*np.pi*f*(32.0*d_12 + 32.0*d_21 + 32.0*d_23 + 18.0*d_32)) + Sa_a*(f**2 + f_tm1**2)*(f**4 + f_tm2**4)*((np.exp(2.0*1j*np.pi*f*(d_13 + d_31)) + np.exp(2.0*1j*np.pi*f*(d_13 + d_23 + d_31 + d_32)) - np.exp(1j*np.pi*f*(4.0*d_13 + 2.0*d_23 + 4.0*d_31 + 2.0*d_32)) - 1)*np.exp(2.0*1j*np.pi*d_32*f) - np.exp(2.0*1j*np.pi*d_32*f) + np.exp(2.0*1j*np.pi*f*(d_13 + d_31 + d_32)) + np.exp(1j*np.pi*f*(2.0*d_13 + 2.0*d_23 + 2.0*d_31 + 4.0*d_32)) - np.exp(1j*np.pi*f*(4.0*d_13 + 2.0*d_23 + 4.0*d_31 + 4.0*d_32)))*((np.exp(1j*np.pi*f*(4.0*d_12 + 4.0*d_21 + 8.0*d_23 + 2.0*d_32)) - np.exp(1j*np.pi*f*(6.0*d_12 + 6.0*d_21 + 8.0*d_23 + 2.0*d_32)) - np.exp(1j*np.pi*f*(6.0*d_12 + 6.0*d_21 + 10.0*d_23 + 4.0*d_32)) + np.exp(1j*np.pi*f*(8.0*d_12 + 8.0*d_21 + 10.0*d_23 + 4.0*d_32)))*np.exp(1j*np.pi*f*(8.0*d_12 + 8.0*d_21 + 4.0*d_23 + 4.0*d_32)) + np.exp(1j*np.pi*f*(12.0*d_12 + 12.0*d_21 + 14.0*d_23 + 8.0*d_32)) - np.exp(1j*np.pi*f*(14.0*d_12 + 14.0*d_21 + 14.0*d_23 + 8.0*d_32)) - np.exp(1j*np.pi*f*(14.0*d_12 + 14.0*d_21 + 16.0*d_23 + 10.0*d_32)) + np.exp(1j*np.pi*f*(16.0*d_12 + 16.0*d_21 + 16.0*d_23 + 10.0*d_32)))*np.exp(1j*np.pi*f*(32.0*d_12 + 32.0*d_21 + 34.0*d_23 + 16.0*d_32)))*np.exp(-1j*np.pi*f*(48.0*d_12 + 48.0*d_21 + 50.0*d_23 + 26.0*d_32))/(np.pi**2*c**2*f**4*f_tm2**4)

